                    if _is_zero(summed):
                        acc = {"rows": acc["rows"], "cols": acc["cols"], "data": None}
                    else:
                        acc = {"rows": acc["rows"], "cols": acc["cols"], "data": summed}
            row.append(acc)
        result.append(row)
    return result


